SELECT DATE_FORMAT(paid_at, 'yyyy-MM') paid_month, CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END paid_cohort, ROUND(AVG(amount), 2) avg_amount, SUM(CASE WHEN method = 'bank_transfer' THEN 1 ELSE 0 END) bank_transfer_count, ROUND(STDDEV(amount), 2) stddev_amount FROM payments GROUP BY 1, 2 HAVING stddev_amount > 72
